      Multiple filters can be used at the same time.
      <br />
      Example:

      {
        "filter":{
           "uuid":[
              {
                 "predicate":"in",
                 "value":[
                    "d25072e3-a184-477f-9de5-9574354618f5",
                    "3b87bf27-3a35-4984-86a2-d38c8c1f50e6"
                 ]
              }
           ]
        },
        "data": {
          "attributes": {
            "component_id": "encoded_component_id"
          }
        }
     }
